{
  "id": 9,
  "css": "img:is([sizes="auto" i], [sizes^="auto," i]) { contain-intrinsic-size: 3000px 1500px }


	img.wp-smiley, img.emoji {
		display: inline !important;
		border: none !important;
		box-shadow: none !important;
		height: 1em !important;
		width: 1em !important;
		margin: 0 0.07em !important;
		vertical-align: -0.1em !important;
		background: none !important;
		padding: 0 !important;
	}



			.wp-block-post-terms.is-style-swt-post-terms-pill a {
				display: inline-block;
				font-size: var(--wp--preset--font-size--x-small);
				padding: 6px 12px;
				border-radius: var(--wp--custom--border-radius--full);
				color: var(--wp--preset--color--body);
				background-color: var(--wp--preset--color--outline);
				margin-right: var(--wp--preset--spacing--xx-small);
				margin-top: var(--wp--preset--spacing--xxx-small);
				margin-bottom: var(--wp--preset--spacing--xxx-small);
				line-height: var(--wp--custom--line-height--initial);
			}

			.is-style-swt-post-terms-pill .wp-block-post-terms__separator {
				display: none;
			}


            .is-style-swt-search-minimal.wp-block-search__button-inside .wp-block-search__button {
                color: var(--wp--preset--color--heading);
                background-color: var(--wp--preset--color--background);
                border-radius: 0;
                margin: 0;
                padding: var(--wp--preset--spacing--xx-small) var(--wp--preset--spacing--xx-small);
            }

            .is-style-swt-search-minimal.wp-block-search__button-inside .wp-block-search__button:hover {
                color: var(--wp--preset--color--heading);
                background-color: var(--wp--preset--color--background);
            }

            .is-style-swt-search-minimal.wp-block-search__button-inside .wp-block-search__inside-wrapper {
                padding: 4px;
                border: 1px solid var(--wp--preset--color--outline);
                border-radius: var(--wp--custom--border-radius--small);
                background-color: var(--wp--preset--color--background);
            }

            .is-style-swt-search-minimal .wp-block-search__input {
                padding-left: var(--wp--preset--spacing--xx-small);
                color: var(--wp--preset--color--heading);
                background-color: var(--wp--preset--color--background);
                border-radius: 0;
                border: 0;
            }

            .is-style-swt-search-minimal.wp-block-search__button-outside .wp-block-search__input, .wp-block-search__no-button .wp-block-search__input{
                border: 1px solid var(--wp--preset--color--outline);
                border-radius: var(--wp--custom--border-radius--small);
            }


			div.is-style-swt-button-secondary .wp-element-button {
                color: var(--wp--preset--color--body);
				background: var(--wp--preset--color--surface);
			}

            div.is-style-swt-button-secondary .wp-element-button:hover {
                color: var(--wp--preset--color--body);
				background: var(--wp--preset--color--surface);
			}


			div.is-style-swt-button-inverse .wp-element-button {
                color: #1F2937;
				background: #fff;
			}

            div.is-style-swt-button-inverse .wp-element-button:hover {
                color: #1F2937;
				background: #fff;
			}


        .is-style-swt-separator-wide-thin-line.wp-block-separator:not(.is-style-wide):not(.is-style-dots){
                max-width: var(--wp--style--global--content-size);
                width: 100%;
                border-width: 1px;
			}


            .is-style-swt-latest-posts-simple {
                color: var(--wp--preset--color--neutral);
            }

            .is-style-swt-latest-posts-simple > li {
                margin-bottom: var(--wp--preset--spacing--x-small);
            }

            .is-style-swt-latest-posts-simple.swt-has-featured-image > li {
                position: relative;
                padding-right: 75px;
            }


            .is-style-swt-latest-posts-simple .wp-block-latest-posts__featured-image {
                position: absolute;
                right: 0;
            }

            .is-style-swt-latest-posts-simple .wp-block-latest-posts__featured-image img {
                object-fit: cover;
                width: 56px;
                height: 56px;
            }

            .is-style-swt-latest-posts-simple a {
                display: block;
                color: var(--wp--preset--color--heading);
                font-size: var(--wp--preset--font-size--small);
                font-weight: var(--wp--custom--font-weight--medium);
            }

            .is-style-swt-latest-posts-simple .wp-block-latest-posts__post-author,.is-style-swt-latest-posts-simple .wp-block-latest-posts__post-date {
                display: inline-block;
                font-size: var(--wp--preset--font-size--x-small);
                font-weight: var(--wp--custom--font-weight--regular);
            }

            .is-style-swt-latest-posts-simple .wp-block-latest-posts__post-author + time:before {
                content:"·";
                padding-right: 5px;
                padding-left: 5px;
                color: var(--wp--preset--color--neutral);
            }

            .is-style-swt-latest-posts-simple .wp-block-latest-posts__post-excerpt {
                font-size: var(--wp--preset--font-size--x-small);
                font-weight: var(--wp--custom--font-weight--regular);
                margin-top: 0.2em;
            }



			.is-style-swt-categories-minimal {
				padding-left: 0;
				list-style: none;
			}

			.is-style-swt-categories-minimal .cat-item {
				font-size: var(--wp--preset--font-size--small);
				margin-bottom: var(--wp--preset--spacing--xx-small);
			}

			.is-style-swt-categories-minimal.wp-block-categories-dropdown select {
				padding-left: var(--wp--preset--spacing--x-small);
				padding-right: var(--wp--preset--spacing--large);
				padding-top: var(--wp--preset--spacing--x-small);
				padding-bottom: var(--wp--preset--spacing--x-small);
				border: 1px solid var(--wp--preset--color--outline);
				border-radius: var(--wp--custom--border-radius--small);
				font-weight: var(--wp--custom--font-weight--regular);
				font-size: var(--wp--preset--font-size--small);
				color: var(--wp--preset--color--heading);
				background-color: var(--wp--preset--color--background);
				width: 100%;
				height: 60px;
				appearance: none;
			}

			.is-style-swt-categories-minimal.wp-block-categories-dropdown select:focus-visible {
				outline-color: var(--wp--preset--color--heading);
			}

			.is-style-swt-categories-minimal.wp-block-categories-dropdown {
				position: relative;
			}

			.is-style-swt-categories-minimal.wp-block-categories-dropdown:after {
				content: "\e900";
				position: absolute;
				font-family: "icomoon" !important;
				font-size: var(--wp--preset--font-size--medium);
				right: 25px;
				top: 50%;
				transform: translateY(-50%);
				pointer-events: none;
				-webkit-font-smoothing: antialiased;
				-moz-osx-font-smoothing: grayscale;
			}


            .is-style-swt-tag-cloud-pill .tag-cloud-link {
                font-size: var(--wp--preset--font-size--x-small) !Important;
                padding: 6px 12px;
				border-radius: var(--wp--custom--border-radius--full);
				color: var(--wp--preset--color--body);
				background-color: var(--wp--preset--color--outline);
				margin-right: var(--wp--preset--spacing--xx-small);
				margin-top: var(--wp--preset--spacing--xxx-small);
                margin-bottom: var(--wp--preset--spacing--xxx-small);
				line-height: var(--wp--custom--line-height--initial);
            }



            .is-style-swt-latest-comments-simple {
                padding: 0;
            }

            .is-style-swt-latest-comments-simple .wp-block-latest-comments__comment-avatar{
                width: 24px;
                height: 24px;
            }

            .is-style-swt-latest-comments-simple.has-avatars .wp-block-latest-comments__comment .wp-block-latest-comments__comment-meta, .is-style-swt-latest-comments-simple.has-avatars .wp-block-latest-comments__comment .wp-block-latest-comments__comment-excerpt {
               margin-left: 35px;
            }

            .is-style-swt-latest-comments-simple .wp-block-latest-comments__comment .wp-block-latest-comments__comment-meta {
                font-size: var(--wp--preset--font-size--small);
                color: var(--wp--preset--color--neutral);
                font-weight: var(--wp--custom--font-weight--regular);
            }

            .is-style-swt-latest-comments-simple .wp-block-latest-comments__comment .wp-block-latest-comments__comment-meta .wp-block-latest-comments__comment-date{
                font-size: var(--wp--preset--font-size--x-small);
                font-weight: var(--wp--custom--font-weight--regular);
                margin-top: 0.36em;
            }

            .is-style-swt-latest-comments-simple .wp-block-latest-comments__comment .wp-block-latest-comments__comment-excerpt p{
                font-size: var(--wp--preset--font-size--x-small);
                font-weight: var(--wp--custom--font-weight--regular);
            }




            .is-style-swt-archives-minimal {
				padding: 0;
				list-style: none;
            }

			.is-style-swt-archives-minimal .cat-item {
				font-size: var(--wp--preset--font-size--small);
				margin-bottom: var(--wp--preset--spacing--xx-small);
            }

			.is-style-swt-archives-minimal.wp-block-archives-dropdown select {
				padding-left: var(--wp--preset--spacing--x-small);
				padding-right: var(--wp--preset--spacing--large);
				padding-top: var(--wp--preset--spacing--x-small);
				padding-bottom: var(--wp--preset--spacing--x-small);
				border: 1px solid var(--wp--preset--color--outline);
				border-radius: var(--wp--custom--border-radius--small);
				font-weight: var(--wp--custom--font-weight--regular);
				font-size: var(--wp--preset--font-size--small);
				color: var(--wp--preset--color--heading);
				background-color: var(--wp--preset--color--background);
				width: 100%;
				height: 60px;
				appearance: none;
            }

			.is-style-swt-archives-minimal.wp-block-archives-dropdown select:focus-visible {
				outline-color: var(--wp--preset--color--heading);
			}

			.is-style-swt-archives-minimal.wp-block-archives-dropdown {
				position: relative;
			}

			.is-style-swt-archives-minimal.wp-block-archives-dropdown:after {
				content: "\e900";
				position: absolute;
				font-family: "icomoon" !important;
				font-size: var(--wp--preset--font-size--medium);
				right: 25px;
				top: 50%;
				transform: translateY(-50%);
				pointer-events: none;
				-webkit-font-smoothing: antialiased;
				-moz-osx-font-smoothing: grayscale;
			}



        .is-style-swt-post-author-simple {
            flex-wrap: inherit;
        }

        .is-style-swt-post-author-simple .wp-block-post-author__avatar  {
            margin-right: 1.8em;
        }

        .is-style-swt-post-author-simple .avatar  {
                width: 95px;
                height: 95px;
                object-fit: cover;
                border-radius: var(--wp--custom--border-radius--full);
			}

            .is-style-swt-post-author-simple .wp-block-post-author__name {
                font-size: var(--wp--preset--font-size--medium);
                font-weight: var(--wp--custom--font-weight--semi-bold);
                color: var(--wp--preset--color--heading);
                line-height: var(--wp--custom--line-height--initial);
                text-transform: capitalize;
                width: 100%;
			}

            .is-style-swt-post-author-simple .wp-block-post-author__bio {
                margin-top: 10px;
